export type { ApplicationRole, SubmitterApprovalState } from '@sport-analytics/contracts';

export type AccountDeletionState =
  | 'active'
  | 'auth_pending'
  | 'auth_failed'
  | 'finalization_pending'
  | 'finalization_failed'
  | 'deleted';

