  accountId: string;
  subject: string;
  displayName: string | null;
  role: ApplicationRole;
  approvalState: SubmitterApprovalState;
  requestedCompetition: { competitionId: string; name: string } | null;
  competitionIds: string[];
  disabled: boolean;
  deletionState: AccountDeletionState;
}

