import { z } from 'zod';

import { apiDateTimeSchema, apiIdentifierSchema } from './api';

export const APPLICATION_ROLES = ['viewer', 'submitter', 'admin'] as const;

export const applicationRoleSchema = z.enum(APPLICATION_ROLES);

/** @deprecated Request-workflow state only. Use applicationRoleSchema for authorization. */
export const submitterApprovalStateSchema = z.enum([
  'not_requested',
  'pending',
  'approved',
  'rejected',
]);

const competitionScopeSchema = z
  .object({
    competitionId: apiIdentifierSchema,
    name: z.string().min(1),
  })
  .strict();

export const currentUserProfileSchema = z
  .object({
    id: apiIdentifierSchema,
    subject: z.string().min(1),
    displayName: z.string().min(1).nullable(),
    role: applicationRoleSchema,
    approvalState: submitterApprovalStateSchema,
    requestedCompetition: competitionScopeSchema.nullable(),
    competitionIds: z
      .array(apiIdentifierSchema)
      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {
        message: 'Competition identifiers must be unique.',
      }),
  })
  .strict();

export const currentUserProfileResponseSchema = z
  .object({
    user: currentUserProfileSchema,
  })
  .strict();

export const accountDeletionRequestSchema = z
  .object({
    confirmation: z.literal('DELETE'),
  })
  .strict();

export const accountDeletionResponseSchema = z
  .object({
    data: z
      .object({
        status: z.literal('deleted'),
        retainedCricketData: z.literal(true),
      })
      .strict(),
  })
  .strict();

export const submitterAccessRequestSchema = z
  .object({
    competitionId: apiIdentifierSchema,
  })
  .strict();

export const submitterAccessRequestResponseSchema = z
  .object({
    data: z
      .object({
        accountId: apiIdentifierSchema,
        approvalState: z.literal('pending'),
        requestedCompetition: competitionScopeSchema,
      })
      .strict(),
  })
  .strict();

export const submitterScopeRequestResponseSchema = z
  .object({
    data: z
      .object({
        accountId: apiIdentifierSchema,
        requestedCompetition: competitionScopeSchema,
      })
      .strict(),
  })
  .strict();

export const administratorCompetitionScopeSchema = competitionScopeSchema;

export const administratorAuditActorSchema = z
  .object({
    id: apiIdentifierSchema,
    displayName: z.string().min(1).nullable(),
  })
  .strict();

export const administratorManagedUserSchema = z
  .object({
    id: apiIdentifierSchema,
    email: z.string().email(),
    displayName: z.string().min(1).nullable(),
    role: applicationRoleSchema,
    approvalState: submitterApprovalStateSchema,
    requestedCompetition: competitionScopeSchema.nullable(),
    competitionScopes: z
      .array(administratorCompetitionScopeSchema)
      .refine(
        (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,
        { message: 'Competition scopes must be unique.' },
      ),
    disabled: z.boolean(),
    updatedAt: apiDateTimeSchema,
    submitterAccessUpdatedAt: apiDateTimeSchema.nullable(),
    submitterAccessUpdatedBy: administratorAuditActorSchema.nullable(),
    previouslyRevoked: z.boolean().default(false),
  })
  .strict();

export const administratorUserManagementResponseSchema = z
  .object({
    data: z
      .object({
        users: z.array(administratorManagedUserSchema),
        availableScopes: z
          .array(administratorCompetitionScopeSchema)
          .refine(
            (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,
            { message: 'Available competition scopes must be unique.' },
          ),
      })
      .strict(),
  })
  .strict();

export const administratorSubmitterAccessUpdateSchema = z
  .object({
    approved: z.boolean(),
    competitionIds: z
      .array(apiIdentifierSchema)
      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {
        message: 'Competition identifiers must be unique.',
      }),
  })
  .strict()
  .superRefine((value, context) => {
    if (value.approved && value.competitionIds.length === 0) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['competitionIds'],
        message: 'Select at least one competition scope before approving a submitter.',
      });
    }

    if (!value.approved && value.competitionIds.length > 0) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['competitionIds'],
        message: 'Revoked submitters cannot retain competition scopes.',
      });
    }
  });

export const administratorSubmitterAccessResponseSchema = z
  .object({
    data: administratorManagedUserSchema,
  })
  .strict();

export const administratorRoleUpdateSchema = z
  .object({
    role: applicationRoleSchema,
  })
  .strict();

const consumerLimitSchema = z.number().int().min(1).max(10_000);

export const apiConsumerIssueSchema = z
  .object({
    name: z.string().trim().min(1).max(120),
    rateLimitPerMinute: consumerLimitSchema.default(60),
    dailyQuota: consumerLimitSchema.default(10_000),
  })
  .strict();

export const apiConsumerKeySchema = z
  .object({
    id: apiIdentifierSchema,
    prefix: z.string().min(1),
    createdAt: apiDateTimeSchema,
    revokedAt: apiDateTimeSchema.nullable(),
  })
  .strict();

export const apiConsumerSchema = z
  .object({
    id: apiIdentifierSchema,
    name: z.string().min(1),
    rateLimitPerMinute: consumerLimitSchema,
    dailyQuota: consumerLimitSchema,
    createdAt: apiDateTimeSchema,
    keys: z.array(apiConsumerKeySchema),
  })
  .strict();

export const apiConsumerIssueResponseSchema = z
  .object({
    data: apiConsumerSchema.extend({ apiKey: z.string().min(1) }),
  })
  .strict();

export const apiConsumerListResponseSchema = z
  .object({ data: z.object({ consumers: z.array(apiConsumerSchema) }).strict() })
  .strict();

export const apiConsumerRotateResponseSchema = z
  .object({ data: apiConsumerSchema.extend({ apiKey: z.string().min(1) }) })
  .strict();

export const apiConsumerPathParametersSchema = z
  .object({ consumerId: apiIdentifierSchema.regex(/^\d+$/) })
  .strict();

const usageDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);

export const consumerUsageQuerySchema = z
  .object({
    from: usageDateSchema.optional(),
    to: usageDateSchema.optional(),
    limit: z.coerce.number().int().min(1).max(100).default(50),
  })
  .strict();

export const consumerUsageEntrySchema = z
  .object({
    date: usageDateSchema,
    endpoint: z.string().min(1),
    statusClass: z.enum(['2xx', '3xx', '4xx', '5xx']),
    requestCount: z.number().int().nonnegative(),
  })
  .strict();

const consumerUsageAggregateSchema = z
  .object({
    from: usageDateSchema,
    to: usageDateSchema,
    totalRequests: z.number().int().nonnegative(),
    entries: z.array(consumerUsageEntrySchema),
  })
  .strict();

export const consumerUsageResponseSchema = z
  .object({
    data: consumerUsageAggregateSchema
      .extend({
        quota: z
          .object({
            limit: consumerLimitSchema,
            used: z.number().int().nonnegative(),
            remaining: z.number().int().nonnegative(),
          })
          .strict(),
      })
      .strict(),
  })
  .strict();

export const administratorApiConsumerUsageResponseSchema = z
  .object({
    data: consumerUsageAggregateSchema
      .extend({
        consumer: apiConsumerSchema.pick({
          id: true,
          name: true,
          rateLimitPerMinute: true,
          dailyQuota: true,
        }),
      })
