  decide(admin: ApplicationAccount, requestId: string, input: ApiAccessDecision): Promise<ApiAccessRequest>;
  generateKey(account: ApplicationAccount, consumerId: string): Promise<{ consumer: ApiConsumer; apiKey: string }>;
  rotateKey(account: ApplicationAccount, consumerId: string): Promise<{ consumer: ApiConsumer; apiKey: string }>;
  revokeOwnKey(account: ApplicationAccount, consumerId: string, keyId: string): Promise<void>;
  getOwnUsage(account: ApplicationAccount, consumerId: string, query: { from: string; to: string; limit: number }): Promise<AdministratorApiConsumerUsageResponse['data']>;
  listConsumers(): Promise<ApiConsumer[]>;
  updateLimits(consumerId: string, limits: { rateLimitPerMinute: number; dailyQuota: number }): Promise<ApiConsumer>;
  revokeAnyKey(consumerId: string, keyId: string): Promise<void>;
}

export function createApiAccessService(
  repository: ApiAccessRepository = createApiAccessRepository(),
  consumers: ApiConsumerService = createApiConsumerService(),
): ApiAccessService {
  return {
    requestAccess(account, input) { return repository.createRequest(account.accountId, input); },
    getOwnAccess(account) { return repository.getOwn(account.accountId); },
    listPending() { return repository.listPending(); },
    decide(admin, requestId, input) { return repository.decide(admin.accountId, requestId, input); },
    async generateKey(account, consumerId) {
      const overview = await repository.getOwn(account.accountId);
      if (!overview.consumer || overview.consumer.id !== consumerId) throw new ApiAccessConflictError();
      if (overview.consumer.keys.some((key) => key.revokedAt === null)) throw new ApiAccessConflictError();
      const result = await consumers.rotate(account, consumerId);
      const { apiKey, ...consumer } = result;
      return { consumer, apiKey };
    },
    async rotateKey(account, consumerId) {
      const result = await consumers.rotate(account, consumerId);
      const { apiKey, ...consumer } = result;
      return { consumer, apiKey };
    },
    revokeOwnKey: (account, consumerId, keyId) => consumers.revoke(account, consumerId, keyId),
    getOwnUsage: (account, consumerId, query) => consumers.usage(account, consumerId, query),
    listConsumers: () => repository.listConsumers(),
    updateLimits: (consumerId, limits) => repository.updateLimits(consumerId, limits.rateLimitPerMinute, limits.dailyQuota),
    revokeAnyKey: (consumerId, keyId) => repository.revokeAnyKey(consumerId, keyId),
  };
}

