const auth = () => ({ getSession: vi.fn().mockResolvedValue({ data: { session: session() } }), onAuthStateChange: vi.fn((_listener: (event: AuthChangeEvent, session: Session | null) => void) => ({ data: { subscription: { id: 'api-access', callback: _listener, unsubscribe: vi.fn() } } })), signOut: vi.fn() }) as unknown as AuthClient;
const requestRecord = (state: 'pending' | 'approved' | 'rejected') => ({ id: '4', requesterAccountId: '11', name: 'Match model', intendedUse: 'Research match predictions.', state, createdAt: '2026-10-04T10:00:00.000Z', reviewedAt: state === 'pending' ? null : '2026-10-04T11:00:00.000Z', reviewedBy: state === 'pending' ? null : { id: '1', displayName: 'Admin' }, reviewReason: state === 'rejected' ? 'Insufficient detail.' : null });
const consumer = { id: '7', name: 'Match model', rateLimitPerMinute: 30, dailyQuota: 2000, createdAt: '2026-10-04T11:00:00.000Z', keys: [] };

