describe('account API access', () => {
  beforeEach(() => { window.localStorage.clear(); });

  test('requests access and shows pending state', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValueOnce(response(200, { data: { request: null, consumer: null } })).mockResolvedValueOnce(response(201, { data: requestRecord('pending') })));
    renderPanel();
    fireEvent.change(await screen.findByLabelText('Consumer or application name'), { target: { value: 'Match model' } });
    fireEvent.change(screen.getByLabelText('Intended use'), { target: { value: 'Research match predictions.' } });
    fireEvent.click(screen.getByRole('button', { name: 'Request API access' }));
    expect(await screen.findByText(/awaiting administrator review/)).toBeInTheDocument();
  });

