    rateLimitPerMinute: 60,
    dailyQuota: 10_000,
    createdAt,
    keys: [{ id: '33', prefix: 'sat_live_test-sa', createdAt, revokedAt: null }],
    ...overrides,
  };
}

function listResponse(consumers: ApiConsumer[] = [consumer()]) {
  return response(200, { data: { consumers } });
}

function usageResponse(
  entries: Array<{
    date: string;
    endpoint: string;
