### apps/frontend/src/features/api-access/ApiAccessPanel.tsx
import type { ApiAccessRequest, ApiConsumer } from '@sport-analytics/contracts';
import { useCallback, useEffect, useState, type FormEvent } from 'react';

import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import {
  generateApiKey,
  getApiAccess,
  getApiUsage,
  requestApiAccess,
  revokeApiKey,
  rotateApiKey,
} from './api-access-api';

type State =
  | { kind: 'loading' }
  | { kind: 'error' }
  | { kind: 'ready'; request: ApiAccessRequest | null; consumer: ApiConsumer | null };

export function ApiAccessPanel() {
  const client = useAuthenticatedApiClient();
  const [state, setState] = useState<State>({ kind: 'loading' });
  const [secret, setSecret] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [usage, setUsage] = useState<number | null>(null);
  const load = useCallback(
    async (signal?: AbortSignal) => {
      setState({ kind: 'loading' });
      try {
        const result = await getApiAccess(client, signal);
        setState({ kind: 'ready', ...result });
      } catch {
        if (!signal?.aborted) setState({ kind: 'error' });
      }
    },
    [client],
  );
  useEffect(() => {
    const controller = new AbortController();
    void load(controller.signal);
    return () => {
      controller.abort();
      setSecret(null);
    };
  }, [load]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setBusy(true);
    const data = new FormData(event.currentTarget);
    try {
      const request = await requestApiAccess(client, {
        name: String(data.get('name') ?? ''),
        intendedUse: String(data.get('intendedUse') ?? ''),
      });
      setState({ kind: 'ready', request, consumer: null });
    } finally {
      setBusy(false);
    }
  }
  async function issue(consumer: ApiConsumer, rotate: boolean) {
    setBusy(true);
    try {
      const result = rotate
        ? await rotateApiKey(client, consumer.id)
        : await generateApiKey(client, consumer.id);
      const { apiKey, ...updated } = result;
      setState((current) =>
        current.kind === 'ready' ? { ...current, consumer: updated } : current,
      );
      setSecret(apiKey);
    } finally {
      setBusy(false);
    }
  }

  return (
    <section aria-labelledby="api-access-title">
      <h2 id="api-access-title">API access</h2>
      {state.kind === 'loading' ? <p role="status">Loading API accessâ€¦</p> : null}
      {state.kind === 'error' ? (
        <>
          <p role="alert">API access could not be loaded.</p>
          <button type="button" className="button button--secondary" onClick={() => void load()}>
            Retry
          </button>
        </>
      ) : null}
      {state.kind === 'ready' && !state.request ? (
        <form onSubmit={(event) => void submit(event)}>
          <p>Request managed API capacity for an external application or integration.</p>
          <label>
            Consumer or application name
            <input name="name" required maxLength={120} />
          </label>
          <label>
            Intended use
            <textarea name="intendedUse" required minLength={10} maxLength={500} />
          </label>
          <button className="button" disabled={busy}>
            {busy ? 'Submittingâ€¦' : 'Request API access'}
          </button>
        </form>
      ) : null}
      {state.kind === 'ready' && state.request?.state === 'pending' ? (
        <p role="status">Your API access request is awaiting administrator review.</p>
      ) : null}
      {state.kind === 'ready' && state.request?.state === 'rejected' ? (
        <div>
          <p>
            Your API access request was rejected
            {state.request.reviewReason ? `: ${state.request.reviewReason}` : '.'}
          </p>
          <button
            className="button button--secondary"
            type="button"
            onClick={() => setState({ kind: 'ready', request: null, consumer: null })}
          >
            Submit a new request
          </button>
        </div>
      ) : null}
      {state.kind === 'ready' && state.consumer ? (
        <div>
          <h3>{state.consumer.name}</h3>
          <p>
            {state.consumer.rateLimitPerMinute} requests per minute; {state.consumer.dailyQuota}{' '}
            requests per UTC day.
          </p>
          {state.consumer.keys.some((key) => key.revokedAt === null) ? (
            <>
              <button
                className="button"
                type="button"
                disabled={busy}
                onClick={() => void issue(state.consumer!, true)}
              >
                Rotate API key
              </button>
              {state.consumer.keys
                .filter((key) => key.revokedAt === null)
                .map((key) => (
                  <button
                    key={key.id}
                    className="button button--secondary"
                    type="button"
                    onClick={async () => {
                      await revokeApiKey(client, state.consumer!.id, key.id);
                      await load();
                    }}
                  >
                    Revoke API key
                  </button>
                ))}
            </>
          ) : (
            <button
              className="button"
              type="button"
              disabled={busy}
              onClick={() => void issue(state.consumer!, false)}
            >
              Generate API key
            </button>
          )}
          <button
            className="button button--secondary"
            type="button"
            onClick={async () =>
              setUsage((await getApiUsage(client, state.consumer!.id)).totalRequests)
            }
          >
            View API usage
          </button>
          {usage !== null ? <p>Requests in the selected usage window: {usage}</p> : null}
        </div>
      ) : null}
      {secret ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="api-key-title"
          onKeyDown={(event) => {
            if (event.key === 'Escape') setSecret(null);
          }}
        >
          <h3 id="api-key-title">Copy your API key now</h3>
          <p>This secret is shown once and is not stored.</p>
          <code>{secret}</code>
          <button className="button" type="button" autoFocus onClick={() => setSecret(null)}>
            I have saved the key
          </button>
        </div>
      ) : null}
    </section>
  );
}

