import type { ApiAccessRequest } from '@sport-analytics/contracts';
import { useState } from 'react';

import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import { decideApiAccessRequest, getPendingApiAccessRequests } from './admin-api';

export function AdminApiAccessRequestsPanel() {
  const client = useAuthenticatedApiClient();
  const [requests, setRequests] = useState<ApiAccessRequest[] | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  async function load() {
    setLoading(true);
    try {
      setRequests(await getPendingApiAccessRequests(client));
    } finally {
      setLoading(false);
    }
  }
  async function decide(
    item: ApiAccessRequest,
    decision: 'approved' | 'rejected',
    form: HTMLFormElement,
  ) {
    setBusy(item.id);
    const data = new FormData(form);
    await decideApiAccessRequest(client, item.id, {
      decision,
      reviewReason: String(data.get('reviewReason') || '') || undefined,
      ...(decision === 'approved'
        ? {
            rateLimitPerMinute: Number(data.get('rateLimitPerMinute')),
            dailyQuota: Number(data.get('dailyQuota')),
          }
        : {}),
    });
    setRequests((current) => current?.filter(({ id }) => id !== item.id) ?? []);
    setBusy(null);
  }
  return (
    <section className="api-consumer-panel" aria-labelledby="access-requests-title">
      <h2 id="access-requests-title">Pending API access requests</h2>
      {requests === null ? (
        <button
          className="button button--secondary"
          type="button"
          disabled={loading}
          onClick={() => void load()}
        >
          {loading ? 'Loading requestsâ€¦' : 'Review pending requests'}
        </button>
      ) : requests.length === 0 ? (
        <p>No pending API access requests.</p>
      ) : (
        requests.map((item) => (
          <form key={item.id} onSubmit={(event) => event.preventDefault()}>
            <h3>{item.name}</h3>
            <p>{item.intendedUse}</p>
            <p>Requested by account {item.requesterAccountId}</p>
            <label>
              Requests per minute
              <input
                name="rateLimitPerMinute"
                type="number"
                min="1"
                max="10000"
                defaultValue="60"
              />
            </label>
            <label>
              Requests per UTC day
              <input name="dailyQuota" type="number" min="1" max="10000" defaultValue="10000" />
            </label>
            <label>
              Review reason (optional)
              <textarea name="reviewReason" maxLength={500} />
            </label>
            <button
              className="button"
              type="button"
              disabled={busy === item.id}
              onClick={(event) => void decide(item, 'approved', event.currentTarget.form!)}
            >
              Approve request
            </button>
            <button
              className="button button--danger"
              type="button"
              disabled={busy === item.id}
              onClick={(event) => void decide(item, 'rejected', event.currentTarget.form!)}
            >
              Reject request
            </button>
          </form>
        ))
      )}
    </section>
  );
}

