import type { ButtonHTMLAttributes } from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'destructive';

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
}

export function Button({ className, type = 'button', variant = 'primary', ...props }: ButtonProps) {
  const classes = ['ui-button', `ui-button--${variant}`, className].filter(Boolean).join(' ');

  return <button {...props} className={classes} type={type} />;
}
import type { InputHTMLAttributes } from 'react';

export interface TextFieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  helpText?: string;
  error?: string;
}

export function TextField({
  className,
  error,
  helpText,
  id,
  label,
  required,
  ...inputProps
}: TextFieldProps) {
  const inputId = id ?? inputProps.name;

  if (!inputId) {
    throw new Error(
      'TextField requires an id or name so its label can be associated with the input.',
    );
  }

  const helpId = helpText ? `${inputId}-help` : undefined;
  const errorId = error ? `${inputId}-error` : undefined;
  const describedBy =
    [inputProps['aria-describedby'], helpId, errorId].filter(Boolean).join(' ') || undefined;

  return (
    <div className="ui-field">
      <label htmlFor={inputId}>
        {label}
        {required ? <span aria-hidden="true"> *</span> : null}
        {required ? <span className="sr-only"> (required)</span> : null}
      </label>
      <input
        {...inputProps}
        aria-describedby={describedBy}
        aria-invalid={error ? true : inputProps['aria-invalid']}
        className={['ui-field__input', className].filter(Boolean).join(' ')}
        id={inputId}
        required={required}
      />
      {helpText ? (
        <p className="ui-field__help" id={helpId}>
          {helpText}
        </p>
      ) : null}
      {error ? (
        <p className="ui-field__error" id={errorId}>
          {error}
        </p>
      ) : null}
    </div>
  );
}
import type { ReactNode } from 'react';

type MessageVariant = 'info' | 'success' | 'warning' | 'error';

export interface MessageProps {
  children: ReactNode;
  heading?: string;
  variant?: MessageVariant;
}

export function Message({ children, heading, variant = 'info' }: MessageProps) {
  const isError = variant === 'error';

  return (
    <section className={`ui-message ui-message--${variant}`} role={isError ? 'alert' : 'status'}>
      {heading ? <h2 className="ui-message__heading">{heading}</h2> : null}
      <div>{children}</div>
    </section>
  );
}
import type { HTMLAttributes, ReactNode } from 'react';

export interface CardProps extends HTMLAttributes<HTMLElement> {
  children: ReactNode;
  heading?: ReactNode;
}

export function Card({ children, className, heading, ...props }: CardProps) {
  return (
    <section {...props} className={['ui-card', className].filter(Boolean).join(' ')}>
      {heading ? <h2 className="ui-card__heading">{heading}</h2> : null}
      {children}
    </section>
  );
}
import type { ReactNode } from 'react';

export interface PageLayoutProps {
  children: ReactNode;
  description?: ReactNode;
  heading: ReactNode;
}

export function PageLayout({ children, description, heading }: PageLayoutProps) {
  return (
    <div className="ui-page-layout content-boundary">
      <header className="ui-page-layout__header">
        <h1>{heading}</h1>
        {description ? <p>{description}</p> : null}
      </header>
      {children}
    </div>
  );
}
