      .set('Authorization', 'Bearer token')
      .expect(201);
    expect(response.body.data.apiKey).toBe('sat_live_once');
    expect(apiAccess.generateKey).toHaveBeenCalledWith(
      expect.objectContaining({ accountId: '11' }),
      '7',
    );
  });
});

